export const LONG = {"30":[{"id":"30A","title":"ตอนเช้า","text":"ทุกเช้าฉันตื่นนอนแล้วรีบแปรงฟัน ล้างหน้า และแต่งตัวไปโรงเรียน แม่เตรียมข้าวต้มร้อน ๆ ไว้ให้บนโต๊ะทุกวัน"},{"id":"30B","title":"ห้องสมุด","text":"ห้องสมุดของโรงเรียนเรามีหนังสือนิทานมากมาย นักเรียนยืมกลับไปอ่านที่บ้านได้ครั้งละสองเล่ม"},{"id":"30C","title":"ฝนตก","text":"ฝนตกหนักตั้งแต่บ่ายจนถึงค่ำ ถนนหน้าบ้านมีน้ำขัง เด็ก ๆ จึงต้องเดินเลียบขอบทางอย่างระมัดระวัง"},{"id":"30D","title":"คุณตากับแมว","text":"คุณตาชอบนั่งอ่านหนังสือพิมพ์ใต้ต้นมะม่วงหลังบ้าน ส่วนแมวสีส้มของเราก็มักจะนอนหลับอยู่ข้าง ๆ คุณตาเสมอ"},{"id":"30E","title":"ปลูกถั่วงอก","text":"วันนี้ครูให้นักเรียนจับคู่กันทำการทดลองปลูกถั่วงอก แล้วจดบันทึกความสูงของต้นถั่วทุกวันเป็นเวลาหนึ่งสัปดาห์"}],"31":[{"id":"31A","title":"ลูกช้างพลายน้อย","text":"กาลครั้งหนึ่ง มีลูกช้างตัวหนึ่งชื่อพลายน้อย มันชอบเล่นน้ำที่ลำธารใกล้หมู่บ้าน วันหนึ่งพลายน้อยเห็นนกตัวเล็กติดอยู่ในพุ่มไม้ริมน้ำ มันจึงใช้งวงค่อย ๆ แหวกกิ่งไม้ออกจนนกบินหนีไปได้ ไม่กี่วันต่อมา นกตัวนั้นบินกลับมาเตือนพลายน้อยว่ามีนายพรานซ่อนอยู่หลังต้นไม้ใหญ่ พลายน้อยจึงพาแม่หนีไปได้อย่างปลอดภัย ความดีที่เราทำย่อมกลับมาช่วยเราเสมอ"},{"id":"31B","title":"ต้นมะเขือเทศ","text":"สมใจปลูกต้นมะเขือเทศไว้ในกระถางหลังบ้าน ทุกเช้าเธอรดน้ำและคอยดูว่ามีหนอนมากินใบหรือไม่ ผ่านไปหนึ่งเดือน ต้นมะเขือเทศเริ่มออกดอกสีเหลืองเล็ก ๆ อีกไม่นานดอกเหล่านั้นก็กลายเป็นผลสีเขียว แล้วค่อย ๆ เปลี่ยนเป็นสีแดง สมใจเก็บผลแรกไปให้คุณยายชิม คุณยายยิ้มและบอกว่าเป็นมะเขือเทศที่อร่อยที่สุดที่เคยกินมา"},{"id":"31C","title":"มดกับตั๊กแตน","text":"ในฤดูร้อนปีหนึ่ง มดตัวเล็ก ๆ ขยันแบกเมล็ดข้าวกลับรังทุกวัน ขณะที่ตั๊กแตนนอนร้องเพลงอยู่บนใบหญ้า ตั๊กแตนหัวเราะและถามว่าทำไมต้องเหนื่อยขนาดนั้น มดตอบว่าอีกไม่นานฝนจะตกหนักและหาอาหารได้ยาก เมื่อฤดูฝนมาถึงจริง ตั๊กแตนหิวโซจนต้องมาขออาหารจากมด มดแบ่งข้าวให้กินและบอกว่า ปีหน้าเรามาช่วยกันเก็บอาหารตั้งแต่เนิ่น ๆ นะ ตั๊กแตนพยักหน้ารับด้วยความละอายใจ"},{"id":"31D","title":"บ้านคุณยาย","text":"ปิดเทอมนี้ภูมิได้ไปเที่ยวบ้านคุณยายที่ต่างจังหวัด บ้านคุณยายอยู่ติดกับทุ่งนากว้าง ตอนเย็นภูมิชอบปั่นจักรยานไปตามคันนาเพื่อดูฝูงนกบินกลับรัง คืนหนึ่งไฟดับทั้งหมู่บ้าน ภูมิกลัวมาก แต่คุณยายจุดเทียนแล้วชวนออกไปนั่งดูดาวที่ลานหน้าบ้าน ภูมิไม่เคยเห็นดาวมากขนาดนี้มาก่อน คุณยายชี้ให้ดูกลุ่มดาวไก่ และเล่าว่าสมัยก่อนคนใช้ดาวบอกทิศทางเวลาเดินทางตอนกลางคืน"},{"id":"31E","title":"เพื่อนใหม่","text":"เช้าวันจันทร์ ห้องเรียนของเรามีเพื่อนใหม่ชื่อมายด์ มายด์เพิ่งย้ายมาจากโรงเรียนอื่นจึงยังไม่รู้จักใคร ช่วงพักกลางวันเธอนั่งกินข้าวอยู่คนเดียว ฉันกับเพื่อนอีกสองคนจึงเดินไปชวนเธอมานั่งด้วยกัน เราคุยกันเรื่องการ์ตูนที่ชอบ และพบว่ามายด์วาดรูปเก่งมาก หลังจากวันนั้น มายด์ก็มีเพื่อนเล่นทุกวัน และยังช่วยวาดภาพประกอบให้รายงานกลุ่มของเราจนได้คะแนนเต็ม"}],"32":[{"id":"32A","title":"วัฏจักรน้ำ","text":"น้ำบนโลกเคลื่อนที่เป็นวัฏจักรไม่มีวันหยุด เมื่อแสงแดดส่องลงบนแม่น้ำ ทะเล และมหาสมุทร น้ำบางส่วนจะระเหยกลายเป็นไอลอยขึ้นสู่ท้องฟ้า เมื่อไอน้ำลอยสูงขึ้นไปเจออากาศเย็น ก็จะควบแน่นเป็นหยดน้ำเล็ก ๆ รวมตัวกันเป็นก้อนเมฆ เมื่อหยดน้ำในเมฆรวมกันจนหนักมากขึ้น ก็จะตกลงมาเป็นฝน น้ำฝนไหลลงสู่ลำธารและแม่น้ำ บางส่วนซึมลงไปใต้ดิน แล้วในที่สุดก็ไหลกลับสู่ทะเลอีกครั้ง วัฏจักรนี้ทำให้โลกของเรามีน้ำจืดใช้อยู่ตลอดเวลา"},{"id":"32B","title":"สงกรานต์","text":"สงกรานต์เป็นประเพณีขึ้นปีใหม่ของไทยที่จัดขึ้นในช่วงกลางเดือนเมษายน ในช่วงนี้ผู้คนจำนวนมากเดินทางกลับบ้านเกิดเพื่อพบครอบครัว ตอนเช้าหลายบ้านจะไปทำบุญตักบาตรที่วัด จากนั้นลูกหลานจะรดน้ำดำหัวผู้ใหญ่ เพื่อแสดงความเคารพและขอพรให้ชีวิตมีความสุข ส่วนการเล่นสาดน้ำนั้นช่วยคลายความร้อนในหน้าร้อน แต่เราควรเล่นอย่างสุภาพ ไม่ใช้น้ำสกปรก และไม่สาดน้ำใส่คนที่ไม่ต้องการเล่น เพื่อให้ทุกคนสนุกและปลอดภัย"},{"id":"32C","title":"การสังเคราะห์ด้วยแสง","text":"พืชสีเขียวสร้างอาหารได้เองด้วยกระบวนการที่เรียกว่าการสังเคราะห์ด้วยแสง ใบของพืชมีสารสีเขียวชื่อคลอโรฟิลล์ ซึ่งทำหน้าที่รับพลังงานจากแสงแดด พืชดูดน้ำจากดินผ่านทางราก และรับแก๊สคาร์บอนไดออกไซด์จากอากาศผ่านทางปากใบ จากนั้นจึงนำทั้งสองอย่างมาสร้างเป็นน้ำตาลเพื่อใช้เป็นอาหาร ในระหว่างนี้พืชจะปล่อยแก๊สออกซิเจนออกมาสู่อากาศ ซึ่งเป็นแก๊สที่คนและสัตว์ต้องใช้ในการหายใจ ดังนั้นการปลูกต้นไม้จึงช่วยให้อากาศรอบตัวเราสดชื่นขึ้น"},{"id":"32D","title":"การนอนหลับ","text":"การนอนหลับเป็นสิ่งสำคัญต่อร่างกายไม่น้อยไปกว่าการกินอาหาร ขณะที่เรานอนหลับ ร่างกายจะซ่อมแซมส่วนที่สึกหรอ และสมองจะจัดเก็บสิ่งที่เราเรียนรู้มาตลอดทั้งวัน เด็กในวัยประถมควรนอนวันละประมาณเก้าถึงสิบสองชั่วโมง ถ้านอนไม่พอ เราจะรู้สึกง่วงในห้องเรียน จำบทเรียนได้ยาก และอารมณ์เสียง่าย วิธีง่าย ๆ ที่ช่วยให้นอนหลับดี คือเข้านอนให้ตรงเวลาทุกคืน ปิดโทรศัพท์และแท็บเล็ตก่อนนอนอย่างน้อยหนึ่งชั่วโมง และไม่กินขนมหวานหรือดื่มน้ำอัดลมในตอนกลางคืน"},{"id":"32E","title":"ความปลอดภัยออนไลน์","text":"เมื่อเราใช้อินเทอร์เน็ต เราควรดูแลข้อมูลส่วนตัวของตัวเองให้ดี ข้อมูลส่วนตัว เช่น ชื่อจริง ที่อยู่ เบอร์โทรศัพท์ และชื่อโรงเรียน ไม่ควรบอกกับคนที่เรารู้จักเพียงในโลกออนไลน์ รหัสผ่านก็ควรตั้งให้เดายาก และไม่บอกใครนอกจากพ่อแม่หรือผู้ปกครอง ถ้ามีคนแปลกหน้าส่งข้อความมาชวนคุย ขอรูปถ่าย หรือชวนออกไปพบกัน เราควรรีบบอกผู้ใหญ่ที่ไว้ใจทันที นอกจากนี้ก่อนจะโพสต์หรือส่งต่ออะไร ให้คิดก่อนเสมอว่าสิ่งนั้นเป็นความจริงหรือไม่ และจะทำให้ใครเสียใจหรือเปล่า"}],"33":[{"id":"33A","title":"ประกาศห้องสมุด","text":"ประกาศจากห้องสมุด วันศุกร์ที่ ๑๖ ตุลาคม ๒๕๖๙ ห้องสมุดเปิดเวลา ๘.๓๐ - ๑๖.๐๐ น. นักเรียนชั้น ป.๓ - ป.๖ ยืมหนังสือได้คนละ ๒ เล่ม (ไม่เกิน ๗ วัน) หากคืนช้าต้องจ่ายค่าปรับวันละ ฿๒ ใครมีคำถาม เช่น \"หนังสือเล่มนี้อยู่ชั้นไหน?\" สอบถามบรรณารักษ์ได้ที่โต๊ะหน้าห้อง ๒๐๕ อาคาร ๓ ทุกวันจันทร์ - ศุกร์"},{"id":"33B","title":"ไปตลาด","text":"แม่ให้เงินฉัน ฿๑๐๐ ไปซื้อของที่ตลาดเช้าวันเสาร์ ฉันซื้อไข่ไก่ ๑๐ ฟอง ราคา ฿๔๕, ผักบุ้ง ๒ กำ กำละ ฿๑๕ และกล้วยหอม ๑ หวี ราคา ฿๒๐ รวมทั้งหมด ฿๙๕ แม่ถามว่า \"ซื้อครบทุกอย่างหรือยัง?\" ฉันตอบว่า \"ครบแล้วจ้ะ เหลือเงินทอน ๕ บาท\" แม่ยิ้มแล้วบอกให้หยอดกระปุกออมสินไว้ ตอนนี้ในกระปุกของฉันมีเงินรวม ฿๒๓๗ ฉันตั้งใจจะเก็บให้ครบ ฿๕๐๐ ภายในวันที่ ๓๑/๑๒/๒๕๖๙"},{"id":"33C","title":"ตารางเรียน","text":"ตารางเรียนวันพุธของชั้น ป.๔/๒ เริ่มคาบแรกเวลา ๘.๓๐ - ๙.๒๐ น. วิชาคณิตศาสตร์ ห้อง ๓๐๑ ต่อด้วยวิชาภาษาไทยเวลา ๙.๒๐ - ๑๐.๑๐ น. พักกลางวันเวลา ๑๑.๕๐ - ๑๒.๔๐ น. ช่วงบ่ายเป็นวิชาคอมพิวเตอร์ (ห้อง ๒๐๔) และวิชาพลศึกษา ซึ่งต้องเปลี่ยนชุดกีฬาก่อนเข้าเรียน ๑๐ นาที ใครลืมนำชุดมา ให้แจ้งครูประจำชั้นก่อนเวลา ๑๓.๐๐ น. ถ้ามีข้อสงสัย เช่น \"วันนี้ต้องนำสีไม้มาด้วยไหม?\" ให้ถามหัวหน้าห้องได้"},{"id":"33D","title":"สูตรน้ำมะนาวโซดา","text":"สูตรน้ำมะนาวโซดาสำหรับ ๔ แก้ว เตรียมน้ำมะนาว ๑/๒ ถ้วย, น้ำเชื่อม ๑/๓ ถ้วย, โซดาเย็น ๓ ถ้วย และน้ำแข็ง ๑๒ - ๑๕ ก้อน วิธีทำ (๑) ผสมน้ำมะนาวกับน้ำเชื่อมให้เข้ากัน (๒) ใส่น้ำแข็งลงในแก้ว แก้วละ ๓ - ๔ ก้อน (๓) เทส่วนผสมลงไปแก้วละ ๓ ช้อนโต๊ะ แล้วเติมโซดาจนเกือบเต็มแก้ว ต้นทุนรวมประมาณ ฿๖๐ ถ้าขายแก้วละ ฿๒๕ จะได้กำไรเท่าไร? ลองคิดดูนะ"},{"id":"33E","title":"ผลฟุตบอลกีฬาสี","text":"ผลการแข่งขันฟุตบอลกีฬาสีวันที่ ๒๒/๑๑/๒๕๖๙ คู่แรก คณะสีแดงชนะคณะสีฟ้า ๓ - ๑ ประตู คู่ที่สอง คณะสีเหลืองเสมอกับคณะสีเขียว ๒ - ๒ ประตู (ตัดสินด้วยการยิงจุดโทษ ๕ - ๔) ผู้ทำประตูสูงสุดคือ ด.ช.ธนา จากคณะสีแดง ยิงได้ ๓ ประตู คณะที่ชนะเลิศจะได้รับถ้วยรางวัลและเงินสนับสนุนกิจกรรม ฿๑,๕๐๐ ส่วนคณะรองชนะเลิศได้รับ ฿๑,๐๐๐ การแข่งขันนัดชิงชนะเลิศจะเริ่มเวลา ๑๕.๓๐ น. ที่สนามหญ้าหน้าอาคาร ๑"}],"34":[{"id":"34A","title":"ป่าชายเลน","text":"ป่าชายเลนเป็นป่าที่ขึ้นอยู่ตามชายฝั่งทะเลและปากแม่น้ำ ซึ่งเป็นบริเวณที่น้ำทะเลขึ้นลงทุกวัน ต้นไม้ในป่าชายเลน เช่น ต้นโกงกาง มีรากค้ำยันที่แผ่ออกจากลำต้นลงไปยึดดินเลน ช่วยให้ต้นไม้ยืนอยู่ได้แม้น้ำจะขึ้นสูง รากเหล่านี้ยังช่วยชะลอคลื่นและลดการกัดเซาะชายฝั่ง ทำให้แผ่นดินริมทะเลไม่พังทลายลงไปเร็วเกินไป ใต้รากไม้ที่ซับซ้อนนั้นเป็นบ้านของสัตว์เล็ก ๆ มากมาย ทั้งปู กุ้ง หอย และลูกปลาหลายชนิด สัตว์เหล่านี้ใช้ป่าชายเลนเป็นที่หลบภัยจนกว่าจะโตพอที่จะออกไปหากินในทะเล เมื่อป่าชายเลนถูกทำลาย จำนวนสัตว์น้ำก็ลดลงตามไปด้วย ชาวประมงที่หาปลาใกล้ชายฝั่งจึงได้รับผลกระทบโดยตรง ปัจจุบันหลายชุมชนจึงช่วยกันปลูกป่าชายเลนเพิ่มขึ้น และตั้งกฎร่วมกันว่าจะไม่ตัดต้นไม้ในเขตป่าที่ปลูกไว้ เพื่อให้ป่าชายเลนเป็นแหล่งอาหารและปกป้องชายฝั่งให้ลูกหลานต่อไป"},{"id":"34B","title":"วันกีฬาสี","text":"วันกีฬาสีของโรงเรียนเริ่มต้นตั้งแต่เช้าตรู่ นักเรียนทุกคนแต่งกายด้วยเสื้อสีของคณะตัวเอง ทั้งสีแดง สีเหลือง สีเขียว และสีฟ้า ขบวนพาเหรดเดินรอบสนามพร้อมเสียงกลองดังสนั่น ต้นข้าวเป็นนักวิ่งของคณะสีเหลือง เขาซ้อมวิ่งทุกเย็นมาตลอดสองเดือน แต่เมื่อถึงวันแข่งจริง ต้นข้าวกลับรู้สึกตื่นเต้นจนมือเย็นเฉียบ ครูพละเดินมาตบไหล่เบา ๆ แล้วบอกว่า ให้หายใจลึก ๆ และวิ่งให้เต็มที่ ไม่ต้องกังวลว่าจะได้ที่เท่าไร เมื่อเสียงนกหวีดดังขึ้น ต้นข้าวออกตัวได้ดีและวิ่งตามคนที่นำอยู่ไม่ห่าง พอถึงโค้งสุดท้าย เขาเร่งฝีเท้าสุดแรงจนแซงขึ้นไปได้หนึ่งคน และเข้าเส้นชัยเป็นอันดับที่สอง เพื่อน ๆ ในคณะวิ่งเข้ามากอดและส่งเสียงเชียร์ดังลั่น แม้จะไม่ได้ที่หนึ่ง แต่ต้นข้าวก็ภูมิใจมาก เพราะเขารู้ว่าตัวเองทำเต็มที่แล้ว และความพยายามตลอดสองเดือนไม่ได้สูญเปล่าเลย"},{"id":"34C","title":"ผึ้งตัวน้อย","text":"ผึ้งเป็นแมลงตัวเล็กที่มีความสำคัญต่อโลกมากกว่าที่หลายคนคิด ในรังผึ้งหนึ่งรังมีผึ้งอาศัยอยู่ร่วมกันเป็นจำนวนมาก โดยแบ่งหน้าที่กันอย่างชัดเจน ผึ้งนางพญามีหน้าที่วางไข่ ผึ้งงานซึ่งเป็นผึ้งเพศเมียทั้งหมดจะคอยทำความสะอาดรัง เลี้ยงตัวอ่อน สร้างรวงรัง และออกไปหาอาหาร ส่วนผึ้งตัวผู้มีหน้าที่ผสมพันธุ์กับนางพญา เมื่อผึ้งงานพบแหล่งดอกไม้ที่มีน้ำหวานมาก มันจะบินกลับรังแล้วเต้นเป็นรูปแบบพิเศษ เพื่อบอกเพื่อน ๆ ว่าดอกไม้อยู่ทางไหนและไกลแค่ไหน ระหว่างที่ผึ้งบินจากดอกหนึ่งไปอีกดอกหนึ่ง เกสรที่ติดตามขนของมันจะตกลงบนดอกไม้ดอกอื่น ทำให้ดอกไม้ผสมเกสรและกลายเป็นผลได้ ผลไม้และผักหลายชนิดที่เรากินกันทุกวันจึงต้องอาศัยผึ้งช่วย หากผึ้งลดจำนวนลง ผลผลิตทางการเกษตรก็จะลดลงตามไปด้วย ปัจจุบันผึ้งในหลายพื้นที่กำลังลดลง เพราะการใช้สารเคมีกำจัดแมลงมากเกินไป และการตัดไม้ทำลายป่าที่เป็นแหล่งอาหาร เราช่วยผึ้งได้ด้วยการปลูกไม้ดอกไว้รอบบ้าน และเมื่อพบรังผึ้งไม่ควรทำลาย แต่ควรบอกผู้ใหญ่ให้ติดต่อผู้เชี่ยวชาญมาย้ายรังไปไว้ในที่ที่ปลอดภัยแทน"},{"id":"34D","title":"พลอยหัดพิมพ์สัมผัส","text":"เมื่อต้นปีการศึกษา พลอยพิมพ์งานในคอมพิวเตอร์ได้ช้ามาก เธอต้องก้มมองแป้นพิมพ์ทุกครั้งก่อนกดตัวอักษร และใช้นิ้วเพียงสองนิ้วจิ้มไปทีละตัว การพิมพ์รายงานสั้น ๆ เพียงหนึ่งหน้าจึงใช้เวลาเกือบทั้งคาบ ครูคอมพิวเตอร์แนะนำให้พลอยลองฝึกพิมพ์สัมผัส โดยวางนิ้วทั้งแปดนิ้วไว้ที่แป้นเหย้า และพยายามไม่ก้มมองแป้นพิมพ์ ช่วงแรกพลอยรู้สึกว่ายากกว่าเดิมมาก เธอพิมพ์ผิดบ่อยจนอยากกลับไปใช้สองนิ้วเหมือนเดิม แต่ครูบอกว่าทุกทักษะต้องใช้เวลา ขอให้ฝึกวันละนิดแต่ทำทุกวัน พลอยจึงตั้งเป้าว่าจะฝึกวันละสิบห้านาทีก่อนทำการบ้าน ผ่านไปหนึ่งเดือน พลอยเริ่มจำตำแหน่งแป้นได้โดยไม่ต้องมอง ผ่านไปสามเดือน เธอพิมพ์ได้เร็วกว่าตอนใช้สองนิ้วเกือบเท่าตัว และไม่ต้องเงยหน้าก้มหน้าจนปวดคออีกต่อไป เมื่อมีการแข่งขันพิมพ์ดีดของโรงเรียน พลอยตัดสินใจลงสมัคร แม้จะไม่ได้รางวัลที่หนึ่ง แต่เธอก็ทำสถิติได้ดีที่สุดของตัวเอง และรู้แล้วว่าความพยายามเล็ก ๆ ที่ทำทุกวันสามารถเปลี่ยนแปลงสิ่งที่เคยคิดว่ายากได้จริง"}]};
